-- Deterministic multi-currency test seed for non-production test DB
-- Currencies: IDR, USD, SGD, EUR
-- Usage: psql "${TEST_DATABASE_URL}" -f prisma/multi_currency_seed.sql

-- Test user
ON CONFLICT (id) DO NOTHING;

-- Categories
ON CONFLICT (id) DO NOTHING;

-- Accounts (one per currency)
ON CONFLICT (id) DO NOTHING;

-- Deterministic transactions per currency
-- IDR: 2 income, 2 expense
ON CONFLICT (id) DO NOTHING;

-- USD: 3 income, 1 expense
ON CONFLICT (id) DO NOTHING;

-- SGD: 1 income, 2 expense
ON CONFLICT (id) DO NOTHING;

-- EUR: 4 income, 1 expense
ON CONFLICT (id) DO NOTHING;

-- End of seed
